pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 {
        return;
    }

    // Tiny inputs: insertion sort is typically faster than general-purpose sorts.
    if n <= 24 {
        insertion_sort(arr);
        return;
    }

    // Nearly-sorted inputs: insertion sort is very fast (close to linear).
    if is_nearly_sorted_adjacent(arr) {
        insertion_sort(arr);
        return;
    }

    // Default: use Rust's optimized unstable sort (introsort-like, good worst-case behavior).
    arr.sort_unstable();
}



// Cheap heuristic: count adjacent inversions; good signal for "almost sorted" data.
fn is_nearly_sorted_adjacent<T: Ord>(arr: &[T]) -> bool {
    let mut bad = 0usize;
    for w in arr.windows(2) {
        if w[0] > w[1] {
            bad += 1;
            if bad > arr.len() / 16 + 1 {
                return false;
            }
        }
    }
    true
}

// Helper function for insertion sort (useful for small arrays)
fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}
